insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('00b4d596-61c5-4a16-b225-ee6216bb80b4', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', null, 'topic'::public.curated_course_node_type, 'Human Evolution as Evidence-Based Inquiry', 'This opening unit frames human evolution as a scientific, interdisciplinary field rather than a simple origin story. Students learn how fossils, artifacts, living primates, ecology, and genomes become evidence.', 0),
  ('1d53783a-31a1-4f69-bf97-ac3c068d66e5', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '00b4d596-61c5-4a16-b225-ee6216bb80b4', 'subtopic'::public.curated_course_node_type, 'Questions, evidence, and inference', 'The point is to understand how paleoanthropologists move from fragmentary evidence to defensible claims.', 0),
  ('c99f2619-b824-4e76-b993-9f851bcec67d', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '1d53783a-31a1-4f69-bf97-ac3c068d66e5', 'concept'::public.curated_course_node_type, 'Kinds of evidence: fossils, tools, sites, genomes, comparative anatomy', null, 0),
  ('909d3387-08fa-4f8d-bf35-391cd403a24c', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '1d53783a-31a1-4f69-bf97-ac3c068d66e5', 'concept'::public.curated_course_node_type, 'Hypotheses, alternative explanations, and uncertainty', null, 1),
  ('d3ab33ed-ce7b-4632-b169-7b059c5a591f', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '1d53783a-31a1-4f69-bf97-ac3c068d66e5', 'concept'::public.curated_course_node_type, 'Why human evolution is a branching history, not a ladder', null, 2),
  ('5a7dc8f1-cc3c-42de-a0b8-7543ed0e6014', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '00b4d596-61c5-4a16-b225-ee6216bb80b4', 'subtopic'::public.curated_course_node_type, 'History of the field', 'Students see how the field changed as new methods, discoveries, and ethical standards challenged older assumptions.', 1),
  ('589ec79b-68bf-4dbc-9121-e3a3578aedc9', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '5a7dc8f1-cc3c-42de-a0b8-7543ed0e6014', 'concept'::public.curated_course_node_type, 'Darwin, Huxley, early comparative anatomy', null, 0),
  ('0853f46c-e598-4c7e-b250-d6a471157cff', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '5a7dc8f1-cc3c-42de-a0b8-7543ed0e6014', 'concept'::public.curated_course_node_type, 'Twentieth-century fossil discoveries and changing species concepts', null, 1),
  ('bc1b5d33-5b4a-46f9-af40-f4abb062c439', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '5a7dc8f1-cc3c-42de-a0b8-7543ed0e6014', 'concept'::public.curated_course_node_type, 'Recent shifts from morphology-only models to integrated genomic evidence', null, 2),
  ('e1d19974-29c0-4834-902e-00402a828793', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '00b4d596-61c5-4a16-b225-ee6216bb80b4', 'subtopic'::public.curated_course_node_type, 'Scientific literacy and public misconceptions', 'The gist is learning how to communicate human evolution clearly in public settings.', 2),
  ('0a7199fe-5011-4c5b-8487-bdeb30211951', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'e1d19974-29c0-4834-902e-00402a828793', 'concept'::public.curated_course_node_type, 'Evolution versus progress myths', null, 0),
  ('64133568-9161-4e2d-b1ac-aa1b7104f2b4', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'e1d19974-29c0-4834-902e-00402a828793', 'concept'::public.curated_course_node_type, 'Common ancestry versus direct descent', null, 1),
  ('ec5006da-67bf-4f1b-af32-6e8db956d183', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'e1d19974-29c0-4834-902e-00402a828793', 'concept'::public.curated_course_node_type, 'How to read popular claims about new fossils or ancient DNA', null, 2),
  ('b4c7a19d-2aa3-4b78-a158-c8e36bee0631', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', null, 'topic'::public.curated_course_node_type, 'Evolutionary Theory, Phylogeny, and Deep Time', 'Human evolution rests on the same mechanisms that explain all life, but it demands comfort with long timescales and branching relationships. This unit gives students the conceptual grammar of the course.', 1),
  ('fa85c90d-d7f0-4a90-b968-04a5a0f2451e', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'b4c7a19d-2aa3-4b78-a158-c8e36bee0631', 'subtopic'::public.curated_course_node_type, 'Natural selection and evolutionary mechanisms', 'Students learn the forces that change populations across generations.', 0),
  ('f930f92c-f75c-4558-861e-b10f0a655ac7', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'fa85c90d-d7f0-4a90-b968-04a5a0f2451e', 'concept'::public.curated_course_node_type, 'Selection, mutation, migration, recombination, and drift', null, 0),
  ('e7e51551-6254-4381-b6cc-2a39aaacb7ff', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'fa85c90d-d7f0-4a90-b968-04a5a0f2451e', 'concept'::public.curated_course_node_type, 'Fitness, adaptation, constraint, and tradeoff', null, 1),
  ('7be9de90-af0d-4d5f-aa38-6a0f81334410', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'fa85c90d-d7f0-4a90-b968-04a5a0f2451e', 'concept'::public.curated_course_node_type, 'Sexual selection and social behavior', null, 2),
  ('6069dbdd-d14d-411c-900c-02573a5f5e01', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'b4c7a19d-2aa3-4b78-a158-c8e36bee0631', 'subtopic'::public.curated_course_node_type, 'Phylogenetic thinking', 'The point is to read evolutionary trees as hypotheses about relationship and descent.', 1),
  ('23de41c5-11fd-40f6-bb6d-325b99cc0659', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '6069dbdd-d14d-411c-900c-02573a5f5e01', 'concept'::public.curated_course_node_type, 'Clades, nodes, sister taxa, and outgroups', null, 0),
  ('d4c9b179-8123-4cb0-9385-8b30235d7aa5', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '6069dbdd-d14d-411c-900c-02573a5f5e01', 'concept'::public.curated_course_node_type, 'Homology, analogy, convergence, and mosaic evolution', null, 1),
  ('48fc5a8c-a4c7-4274-bd8c-194552e33940', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '6069dbdd-d14d-411c-900c-02573a5f5e01', 'concept'::public.curated_course_node_type, 'Parsimony, likelihood, and molecular clocks at a conceptual level', null, 2),
  ('44f6090a-f887-45f8-83a7-98baa4107562', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'b4c7a19d-2aa3-4b78-a158-c8e36bee0631', 'subtopic'::public.curated_course_node_type, 'Geologic time and chronology', 'Students practice anchoring fossils and events in deep time.', 2),
  ('34da1066-2d33-43c7-b889-7bdc7f1eb994', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '44f6090a-f887-45f8-83a7-98baa4107562', 'concept'::public.curated_course_node_type, 'Epochs relevant to human evolution: Miocene, Pliocene, Pleistocene, Holocene', null, 0),
  ('66447d9c-2142-4381-8746-bc14712c0087', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '44f6090a-f887-45f8-83a7-98baa4107562', 'concept'::public.curated_course_node_type, 'Relative and absolute dating logic', null, 1),
  ('b97b7c66-de52-40ec-8e36-5047f75eecea', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '44f6090a-f887-45f8-83a7-98baa4107562', 'concept'::public.curated_course_node_type, 'Uncertainty ranges and correlation across sites', null, 2),
  ('605cfcd5-5df7-441b-9782-559bb2b361f4', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', null, 'topic'::public.curated_course_node_type, 'Genetics, Genomics, and Population History', 'Modern human evolution cannot be world class without genomics. This unit connects inheritance, population genetics, ancient DNA, and ethical interpretation.', 2),
  ('badc3ed1-d119-4677-b658-fb29b2708b62', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '605cfcd5-5df7-441b-9782-559bb2b361f4', 'subtopic'::public.curated_course_node_type, 'Inheritance and population variation', 'The point is to connect individual inheritance to population-level evolutionary change.', 0),
  ('1a1a0092-dbda-4da3-b813-cb516686248e', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'badc3ed1-d119-4677-b658-fb29b2708b62', 'concept'::public.curated_course_node_type, 'Alleles, genotype, phenotype, and environment', null, 0),
  ('588a3c9b-16db-45f1-a333-50b9ac4986b3', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'badc3ed1-d119-4677-b658-fb29b2708b62', 'concept'::public.curated_course_node_type, 'Hardy-Weinberg reasoning and its limits', null, 1),
  ('1d023bc9-eb07-4d3a-a39b-424a5d521c66', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'badc3ed1-d119-4677-b658-fb29b2708b62', 'concept'::public.curated_course_node_type, 'Population structure, admixture, and founder effects', null, 2),
  ('3ba808f5-8e04-463f-b047-9c9ceacf2805', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '605cfcd5-5df7-441b-9782-559bb2b361f4', 'subtopic'::public.curated_course_node_type, 'Genomics and ancient DNA', 'Students learn how genomes revise fossil-only models and reveal contact among human groups.', 1),
  ('6f06a43b-1e26-42fc-a9bc-9e5d30b0023e', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '3ba808f5-8e04-463f-b047-9c9ceacf2805', 'concept'::public.curated_course_node_type, 'Mitochondrial DNA, Y chromosomes, autosomal genomes', null, 0),
  ('b8e18819-5d51-4103-9289-7618d2f39928', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '3ba808f5-8e04-463f-b047-9c9ceacf2805', 'concept'::public.curated_course_node_type, 'Ancient DNA preservation, contamination, and sampling bias', null, 1),
  ('3d9a2a69-3685-4ddd-9020-cd75ffb3aeb2', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '3ba808f5-8e04-463f-b047-9c9ceacf2805', 'concept'::public.curated_course_node_type, 'Introgression from Neanderthals, Denisovans, and other archaic groups', null, 2),
  ('7d4e3c07-8ed0-4273-a0de-a0c18352a9b7', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '605cfcd5-5df7-441b-9782-559bb2b361f4', 'subtopic'::public.curated_course_node_type, 'Responsible genetic interpretation', 'The gist is to avoid genetic determinism while still taking genomic evidence seriously.', 2),
  ('051738d1-a7c3-40a8-b68c-a41139b5bfe3', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '7d4e3c07-8ed0-4273-a0de-a0c18352a9b7', 'concept'::public.curated_course_node_type, 'Traits shaped by many genes and environments', null, 0),
  ('f11dc756-95ba-4200-a50e-435ac83f8ef4', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '7d4e3c07-8ed0-4273-a0de-a0c18352a9b7', 'concept'::public.curated_course_node_type, 'Limits of ancestry inference', null, 1),
  ('be1bc47f-ceed-4f6e-8e56-17402bd0e6f9', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '7d4e3c07-8ed0-4273-a0de-a0c18352a9b7', 'concept'::public.curated_course_node_type, 'Consent, Indigenous data sovereignty, and community collaboration', null, 2),
  ('f2ef9819-67d0-4e13-9f6b-871c5c183592', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', null, 'topic'::public.curated_course_node_type, 'Primate Comparisons and the Last Common Ancestor', 'Living primates are not ancestors, but they are essential comparisons. This unit uses primate anatomy, behavior, ecology, and cognition to infer what may be ancient, derived, or convergent in humans.', 3);
