values
  ('536e3a26-4206-4621-9082-11e42674bf63', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'f2ef9819-67d0-4e13-9f6b-871c5c183592', 'subtopic'::public.curated_course_node_type, 'Primate taxonomy and adaptation', 'Students learn where humans fit in primate diversity and why classification matters.', 0),
  ('6a1089e4-f6c8-4f67-8ddc-3e64a4336e3a', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '536e3a26-4206-4621-9082-11e42674bf63', 'concept'::public.curated_course_node_type, 'Strepsirrhines, haplorhines, monkeys, apes, and hominins', null, 0),
  ('78ec49e7-91e9-4a2a-928f-037e25967a66', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '536e3a26-4206-4621-9082-11e42674bf63', 'concept'::public.curated_course_node_type, 'Dental, locomotor, sensory, and reproductive traits', null, 1),
  ('d6b41f82-6b4b-4aca-a824-2bed72c844f5', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '536e3a26-4206-4621-9082-11e42674bf63', 'concept'::public.curated_course_node_type, 'Ecological niches and life-history variation', null, 2),
  ('e94b25ca-d026-4261-a6e5-4b0d7916232b', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'f2ef9819-67d0-4e13-9f6b-871c5c183592', 'subtopic'::public.curated_course_node_type, 'Ape behavior and social life', 'The point is to compare patterns of cooperation, aggression, learning, and communication.', 1),
  ('21a15f26-a68f-4983-83a3-e605c1f9464e', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'e94b25ca-d026-4261-a6e5-4b0d7916232b', 'concept'::public.curated_course_node_type, 'Chimpanzees, bonobos, gorillas, orangutans, and gibbons', null, 0),
  ('df7c85fd-9f84-4675-9d6d-49d91395cfd6', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'e94b25ca-d026-4261-a6e5-4b0d7916232b', 'concept'::public.curated_course_node_type, 'Tool use, hunting, sharing, and cultural transmission', null, 1),
  ('bdd2d9da-1c65-4e2e-8a24-2098075af7c6', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'e94b25ca-d026-4261-a6e5-4b0d7916232b', 'concept'::public.curated_course_node_type, 'Dominance, kinship, alliance, and care', null, 2),
  ('1445aaa2-4238-4087-8d7a-36f04817faad', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'f2ef9819-67d0-4e13-9f6b-871c5c183592', 'subtopic'::public.curated_course_node_type, 'Reconstructing the last common ancestor', 'Students learn why the last common ancestor is a hypothesis, not a living chimpanzee.', 2),
  ('847eb934-bc9a-4e68-be4b-0082f3dba6f6', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '1445aaa2-4238-4087-8d7a-36f04817faad', 'concept'::public.curated_course_node_type, 'Mosaic traits and missing fossil evidence', null, 0),
  ('005b1258-2939-4640-9ae2-7b033f5a9245', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '1445aaa2-4238-4087-8d7a-36f04817faad', 'concept'::public.curated_course_node_type, 'Miocene ape diversity', null, 1),
  ('9fccd204-9778-436a-ac5e-905d0d8e67c7', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '1445aaa2-4238-4087-8d7a-36f04817faad', 'concept'::public.curated_course_node_type, 'Locomotion, diet, and social behavior models', null, 2),
  ('edd20418-d267-4efc-920f-9254a9fe28d0', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', null, 'topic'::public.curated_course_node_type, 'Fossils, Taphonomy, Dating, and Paleoenvironmental Reconstruction', 'Fossils are data only after students understand how they form, survive, and get interpreted. This unit trains careful reading of sites, layers, dates, and environmental context.', 4),
  ('cd4a6ee7-4dad-40bb-a5de-1255fab0b8ed', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'edd20418-d267-4efc-920f-9254a9fe28d0', 'subtopic'::public.curated_course_node_type, 'Taphonomy and fossilization', 'The goal is to understand what the fossil record preserves and what it filters out.', 0),
  ('d123bacd-f57e-479a-926a-a979748a99da', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'cd4a6ee7-4dad-40bb-a5de-1255fab0b8ed', 'concept'::public.curated_course_node_type, 'Death assemblages, transport, burial, and preservation', null, 0),
  ('c7137f80-47b6-487c-bbec-f96ee773e309', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'cd4a6ee7-4dad-40bb-a5de-1255fab0b8ed', 'concept'::public.curated_course_node_type, 'Bias by habitat, bone type, and discovery history', null, 1),
  ('fb662b73-7d6b-4ac8-aef8-e0ab6ac83eaa', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'cd4a6ee7-4dad-40bb-a5de-1255fab0b8ed', 'concept'::public.curated_course_node_type, 'Distinguishing behavior from preservation pattern', null, 2),
  ('c69d5936-2a59-4a1f-8384-749a644c85ba', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'edd20418-d267-4efc-920f-9254a9fe28d0', 'subtopic'::public.curated_course_node_type, 'Dating methods', 'Students learn how ages are established and why multiple methods strengthen claims.', 1),
  ('5f31a0b0-c512-4ee6-a75f-c9d57673fb11', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'c69d5936-2a59-4a1f-8384-749a644c85ba', 'concept'::public.curated_course_node_type, 'Stratigraphy, biostratigraphy, paleomagnetism', null, 0),
  ('763e953a-bbac-430e-9b3a-6188a4180484', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'c69d5936-2a59-4a1f-8384-749a644c85ba', 'concept'::public.curated_course_node_type, 'Radiometric approaches such as potassium-argon and argon-argon', null, 1),
  ('ec41297e-2051-4e8b-9c42-a14a9d865666', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'c69d5936-2a59-4a1f-8384-749a644c85ba', 'concept'::public.curated_course_node_type, 'Luminescence, electron spin resonance, and calibration problems', null, 2),
  ('07ec3ccf-bf1b-42bb-ab8c-b817d7ddc8b2', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'edd20418-d267-4efc-920f-9254a9fe28d0', 'subtopic'::public.curated_course_node_type, 'Paleoenvironmental reconstruction', 'The point is to place hominins in changing landscapes rather than isolated specimens.', 2),
  ('cb05de40-cdfb-4f7f-b662-78f7f4cf48a6', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '07ec3ccf-bf1b-42bb-ab8c-b817d7ddc8b2', 'concept'::public.curated_course_node_type, 'Stable isotopes, faunal communities, pollen, and sediments', null, 0),
