  ('f132087f-6355-47c8-9f4a-50e2d9f61b05', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '72a61c86-d961-45e2-8bda-c085de240c81', 'concept'::public.curated_course_node_type, 'Sahelanthropus, Orrorin, Ardipithecus, and early Australopithecus', null, 0),
  ('f3173f5b-43de-4c83-9682-3e8234122e32', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '72a61c86-d961-45e2-8bda-c085de240c81', 'concept'::public.curated_course_node_type, 'Canine reduction, foramen magnum position, and postcranial hints', null, 1),
