  ('9311abee-2136-4574-802b-e4b9f2698196', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'c573aa4f-44f7-44eb-9315-ec8680b88ef4', 'subtopic'::public.curated_course_node_type, 'Anatomy of bipedalism', 'The gist is to connect bones to movement.', 1),
  ('d979e2b4-174e-4f51-b671-4569541ec766', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '9311abee-2136-4574-802b-e4b9f2698196', 'concept'::public.curated_course_node_type, 'Pelvis, femur, knee, foot arches, and spine', null, 0),
