  ('7a241a06-314b-4495-b8dc-e9105b69302d', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'be904b89-9f82-4835-b771-d543e0fbc634', 'concept'::public.curated_course_node_type, 'Arboreal traits and terrestrial adaptations', null, 0),
  ('657bffa8-82a4-45c6-892b-de92bd8cd3c3', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'be904b89-9f82-4835-b771-d543e0fbc634', 'concept'::public.curated_course_node_type, 'Woodland, savanna, and mosaic environments', null, 1),
  ('d4cbe8bf-8bfe-4ce8-b638-69de281233b2', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'be904b89-9f82-4835-b771-d543e0fbc634', 'concept'::public.curated_course_node_type, 'Tradeoffs in speed, endurance, and safety', null, 2),
