  ('eebbf705-8b13-4875-8d8d-922f8c9a1c50', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '99dbfc08-01b3-4cc3-ab34-2b97c500fdd0', 'concept'::public.curated_course_node_type, 'Predation, scavenging, and landscape risk', null, 1),
  ('74ed4291-edd8-4144-aea9-418febd0c7d3', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '99dbfc08-01b3-4cc3-ab34-2b97c500fdd0', 'concept'::public.curated_course_node_type, 'Tool-use possibilities before genus Homo', null, 2),
