  ('0bee341f-3213-42cc-85cb-a64d432d5018', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '60b4c5f8-e074-4fde-92d0-7b837d000e9f', 'concept'::public.curated_course_node_type, 'Brain expansion and dental reduction', null, 1),
  ('61f02aec-57a1-4a4c-b17e-3250c0a3c61d', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '60b4c5f8-e074-4fde-92d0-7b837d000e9f', 'concept'::public.curated_course_node_type, 'Growth, childhood, and aging evidence', null, 2),
  ('1efc7315-427b-4768-baaa-92e6c4d7a48c', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '562ae353-8999-4e63-b4bd-c9f8c5c24f90', 'subtopic'::public.curated_course_node_type, 'Acheulean technology and fire', 'The point is to understand technologies that reshaped behavior.', 1),
  ('4fc535bf-c3ff-4af5-bd65-2ec8d051964c', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '1efc7315-427b-4768-baaa-92e6c4d7a48c', 'concept'::public.curated_course_node_type, 'Handaxes, cleavers, and bifacial skill', null, 0),
