  ('f231b86e-cb14-44a8-8b09-c6b68c9a666c', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '1efc7315-427b-4768-baaa-92e6c4d7a48c', 'concept'::public.curated_course_node_type, 'Planning depth and raw material transport', null, 2),
