  ('673920f0-d448-4f08-a077-11936bfc0f69', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '05a0071a-a074-471e-9fac-23fd61569e27', 'concept'::public.curated_course_node_type, 'Dmanisi, East Asia, Southeast Asia, and island contexts', null, 0),
  ('62268b12-06b1-4769-acb5-955898ed3174', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '05a0071a-a074-471e-9fac-23fd61569e27', 'concept'::public.curated_course_node_type, 'Corridors, climate pulses, and ecological opportunity', null, 1),
  ('95a33d9d-d753-4f25-8b79-94cacc2a1eac', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '05a0071a-a074-471e-9fac-23fd61569e27', 'concept'::public.curated_course_node_type, 'Regional variation within erectus-like populations', null, 2),
  ('32255e03-4989-4015-9ea0-798152afca33', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', null, 'topic'::public.curated_course_node_type, 'Middle Pleistocene Humans and the Road to Later Homo', 'The Middle Pleistocene is messy in the best scientific sense: many fossils, changing species names, and major divergence events. This unit trains students to handle uncertainty without oversimplifying.', 9),
  ('069867ac-8987-4b6d-a786-39ecc320ac2c', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '32255e03-4989-4015-9ea0-798152afca33', 'subtopic'::public.curated_course_node_type, 'Species and taxonomy debates', 'The goal is to compare models of Homo heidelbergensis, rhodesiensis, antecessor, and related forms.', 0),
