  ('421c4da0-1761-4793-b135-4c4a17f7cdf2', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'ef34c388-cfb2-4243-b1f6-7ba73cb07d86', 'concept'::public.curated_course_node_type, 'Why extinction is not the same as genetic disappearance', null, 2),
  ('433ebb6a-fa66-4d2f-bc30-c405180f0f5b', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', null, 'topic'::public.curated_course_node_type, 'Origins and Dispersals of Homo sapiens', 'This unit studies our species as an African lineage with complex dispersals, repeated contacts, and regional ecological adaptations. It avoids both triumphalist and simplistic migration narratives.', 11),
