  ('87d09e3c-6786-4061-9db9-6668f9a58c1c', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '9a6886a5-a0c2-4597-884d-2f911f5a9beb', 'concept'::public.curated_course_node_type, 'Jebel Irhoud, Omo Kibish, Herto, and other African fossils', null, 0),
  ('8603ad6b-69ac-464b-b98f-7680384bb3d6', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '9a6886a5-a0c2-4597-884d-2f911f5a9beb', 'concept'::public.curated_course_node_type, 'Morphological modernity as a mosaic', null, 1),
