  ('730aa9fc-80bc-443b-9ac4-c7e75d3e0e5a', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '5404f0cb-a945-421e-93ad-51f12a97dbfe', 'concept'::public.curated_course_node_type, 'Debates over gradual versus rapid behavioral change', null, 2),
