  ('d1c94f78-b87c-4a8e-bb70-9196b14d2d00', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'f8ffc5dd-3d04-45b6-b477-840cb6eff03a', 'concept'::public.curated_course_node_type, 'Vocal tract, brain lateralization, FOXP2, and hearing anatomy', null, 0),
  ('e1fb71e2-bd3f-4204-99e3-d3e6382d7081', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', 'f8ffc5dd-3d04-45b6-b477-840cb6eff03a', 'concept'::public.curated_course_node_type, 'Gesture, vocal learning, and multimodal communication', null, 1);
