  ('cbacf936-d2c6-4929-aaba-a0d440c4cab7', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '97bdc882-1854-4d99-af39-7aecb28ffd8a', 'concept'::public.curated_course_node_type, 'Clines versus discrete racial types', null, 1),
  ('4726c092-7fb5-4b5e-a29b-1422caab8581', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '97bdc882-1854-4d99-af39-7aecb28ffd8a', 'concept'::public.curated_course_node_type, 'Forensic ancestry estimation and its limits', null, 2),
  ('852aef6d-0b14-4b9e-8582-a09f518895c5', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '866a7940-c4e4-4601-ba44-541fc40008ac', 'subtopic'::public.curated_course_node_type, 'Misuse and responsible communication', 'The gist is to confront scientific racism and communicate evidence clearly.', 2),
