  ('1515bb1d-ddf7-4824-89e7-8a2bc5a893d4', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '8c2a36ec-482b-4272-9146-adc214fedfd8', 'concept'::public.curated_course_node_type, 'Diet, activity, sleep, reproduction, and chronic disease', null, 0),
  ('d18826c6-8ecd-41df-93ae-241b8ce3a042', 'c7d8e9f0-1a2b-4d17-8e67-7f8a9b0c1d77', '8c2a36ec-482b-4272-9146-adc214fedfd8', 'concept'::public.curated_course_node_type, 'Built environments and sedentary behavior', null, 1),
